using Mbb.Archive.Modules.Retention.Application.Queries;
using Mbb.Archive.Modules.Retention.Application.Abstractions;
using Mbb.Archive.BuildingBlocks.Application;
using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;using Mbb.Archive.BuildingBlocks.Presentation;using Mbb.Archive.Modules.Retention.Application.Holds.Place;using Mbb.Archive.Modules.Retention.Application.Holds.Release;using Mbb.Archive.Modules.Retention.Application.Rules.Create;using Mbb.Archive.Modules.Retention.Domain.Rules;
namespace Mbb.Archive.Modules.Retention.Presentation;public static class RetentionEndpoints{public static IEndpointRouteBuilder MapRetentionEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/v1/retention").WithTags("Retention").RequireAuthorization();g.MapGet("/cases",ListCases).RequireAuthorization("permission:retention.read");g.MapGet("/rules",ListRules).RequireAuthorization("permission:retention.read");g.MapGet("/cases/{id:guid}/legal-holds",ListHolds).RequireAuthorization("permission:retention.read");g.MapPost("/rules",async(CreateRuleRequest r,CreateRetentionRuleCommandHandler h,CancellationToken ct)=>{var x=await h.Handle(new CreateRetentionRuleCommand(r.Code,r.Name,r.RetentionMonths,r.Action),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.Created($"/api/v1/retention/rules/{x.Value}",new{id=x.Value});}).RequireAuthorization("permission:retention.rules.manage");g.MapPost("/cases/{id:guid}/legal-holds",async(Guid id,PlaceHoldRequest r,HttpContext http,PlaceLegalHoldCommandHandler h,CancellationToken ct)=>{var subject=http.User.FindFirst("sub")?.Value??http.User.Identity?.Name??"unknown";var x=await h.Handle(new PlaceLegalHoldCommand(id,r.Reason,subject),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.Created($"/api/v1/retention/cases/{id}/legal-holds/{x.Value}",new{id=x.Value});}).RequireAuthorization("permission:retention.holds.manage");g.MapPost("/cases/{id:guid}/legal-holds/release",async(Guid id,ReleaseLegalHoldCommandHandler h,CancellationToken ct)=>{var x=await h.Handle(new ReleaseLegalHoldCommand(id),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.NoContent();}).RequireAuthorization("permission:retention.holds.manage");return e;}private sealed record CreateRuleRequest(string Code,string Name,int RetentionMonths,DispositionAction Action);private static async Task<IResult> ListCases(int? page,int? pageSize,string? status,string? action,bool? heldOnly,RetentionQueryHandlers h,CancellationToken ct){var x=await h.Handle(new GetRetentionCasesQuery(page??1,pageSize??PageRequest.DefaultPageSize,new RetentionCaseFilter(status,action,heldOnly??false)),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.Ok(x.Value);}
private static async Task<IResult> ListRules(RetentionQueryHandlers h,CancellationToken ct){var x=await h.Handle(new GetRetentionRulesQuery(),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.Ok(x.Value);}
private static async Task<IResult> ListHolds(Guid id,RetentionQueryHandlers h,CancellationToken ct){var x=await h.Handle(new GetLegalHoldsQuery(id),ct);return x.IsFailure?ApiResults.Problem(x.Error):Results.Ok(x.Value);}
private sealed record PlaceHoldRequest(string Reason);}
